import requests
import secrets
import string

def random_string(length=10):
    alphabet = string.ascii_letters + string.digits  # A-Z, a-z, 0-9
    return ''.join(secrets.choice(alphabet) for _ in range(length))

def do_get(url, params=None):
    try:
        print("#************************************")
        print(f"GET {url}")
        resp = requests.get(url, params=params, allow_redirects=False)
        status = resp.status_code
        try:
            data = resp.json()
        except ValueError:
            data = resp.text
        print(f"GET {url} -> Status: {status}")
        print("#************************************")
        print()
        return status, data
    except Exception as e:
        print(f"GET {url} failed: {e}")
        return None, None

def do_post(url, data=None, json=None):
    try:
        print("#************************************")
        print(f"POST {url}")
        print(f"body: {json}")
        resp = requests.post(url, data=data, json=json)
        status = resp.status_code
        try:
            data = resp.json()
        except ValueError:
            data = resp.text
        print(f"POST {url} -> Status: {status}")
        print("#************************************")
        print()
        return status, data
    except Exception as e:
        print(f"POST {url} failed: {e}")
        return None, None

if __name__ == "__main__":
    post_url = "http://localhost:5000/api/shorten"
    post_body = {
        "url": f"http://www.google.com/{random_string()}"
    }

    # valid POST case
    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 201
    short_code = post_data["short_code"]
    short_url = post_data["short_url"]
    origin_url = post_body["url"]

    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 200
    assert short_code == post_data["short_code"]

    # invalid POST case
    # invalid method
    rsp_status, get_data = do_get(post_url)
    assert rsp_status == 405

    # invalid input
    rsp_status, post_data = do_post(post_url)
    assert rsp_status == 400

    # invalid format
    post_body["url"] = "www.google.com"
    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 400

    # invalid format
    post_body["url"] = "ht://www.google.com"
    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 400

    # unsupported scheme
    post_body["url"] = "ftp://www.google.com"
    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 400

    # invalid format
    post_body["url"] = "http://www.google.com:abc"
    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 400

    # url too long
    post_body["url"] = "https://www.google.com/search?"
    rsp_status, post_data = do_post(post_url, json=post_body)
    assert rsp_status == 400

    # valid short url
    rsp_status, get_data = do_get(short_url)
    assert rsp_status == 302
    assert origin_url in get_data

    # invalid short url
    # too short
    rsp_status, get_data = do_get("http://localhost:5000/abc")
    assert rsp_status == 400

    # too long
    rsp_status, get_data = do_get("http://localhost:5000/abc123456789")
    assert rsp_status == 400

